-- =============================================================================
-- V4: Orders, order items, payments, refunds, webhooks, inventory ledger
-- Fulfillment status (Orders.Status) is tracked separately from payment
-- status (Orders.PaymentStatus). All amounts are computed by the backend.
-- No raw card data is ever stored (only provider references, brand, last4).
-- =============================================================================

-- Order numbers: ORD-<yyyyMMdd>-<sequence>, generated by the application from this sequence
CREATE SEQUENCE dbo.OrderNumberSeq AS BIGINT START WITH 100001 INCREMENT BY 1 NO CYCLE CACHE 50;

CREATE TABLE dbo.Orders (
    Id                 BIGINT IDENTITY(1,1) NOT NULL,
    OrderNumber        VARCHAR(32)    NOT NULL,
    UserId             BIGINT         NOT NULL,
    Status             VARCHAR(16)    NOT NULL CONSTRAINT DF_Orders_Status DEFAULT 'PENDING',
    PaymentStatus      VARCHAR(20)    NOT NULL CONSTRAINT DF_Orders_PaymentStatus DEFAULT 'PENDING',
    Currency           CHAR(3)        NOT NULL,
    Subtotal           DECIMAL(19,4)  NOT NULL,          -- sum of line totals before order-level discount
    DiscountTotal      DECIMAL(19,4)  NOT NULL CONSTRAINT DF_Orders_DiscountTotal DEFAULT 0,
    ShippingTotal      DECIMAL(19,4)  NOT NULL CONSTRAINT DF_Orders_ShippingTotal DEFAULT 0,
    TaxTotal           DECIMAL(19,4)  NOT NULL CONSTRAINT DF_Orders_TaxTotal DEFAULT 0,
    GrandTotal         DECIMAL(19,4)  NOT NULL,
    RefundedTotal      DECIMAL(19,4)  NOT NULL CONSTRAINT DF_Orders_RefundedTotal DEFAULT 0,
    CouponId           BIGINT         NULL,
    CouponCode         VARCHAR(40)    NULL,              -- snapshot
    ShippingMethodId   BIGINT         NULL,
    ShippingMethodName NVARCHAR(100)  NULL,              -- snapshot
    CustomerNote       NVARCHAR(500)  NULL,
    IdempotencyKey     VARCHAR(64)    NOT NULL,          -- client-generated per checkout attempt
    PlacedAt           DATETIME2(3)   NOT NULL CONSTRAINT DF_Orders_PlacedAt DEFAULT SYSUTCDATETIME(),
    PaidAt             DATETIME2(3)   NULL,
    ShippedAt          DATETIME2(3)   NULL,
    DeliveredAt        DATETIME2(3)   NULL,
    CancelledAt        DATETIME2(3)   NULL,
    CancelReason       NVARCHAR(255)  NULL,
    CreatedAt          DATETIME2(3)   NOT NULL CONSTRAINT DF_Orders_CreatedAt DEFAULT SYSUTCDATETIME(),
    UpdatedAt          DATETIME2(3)   NOT NULL CONSTRAINT DF_Orders_UpdatedAt DEFAULT SYSUTCDATETIME(),
    Version            BIGINT         NOT NULL CONSTRAINT DF_Orders_Version DEFAULT 0,
    CONSTRAINT PK_Orders PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT UQ_Orders_OrderNumber UNIQUE (OrderNumber),
    -- Retried checkout submissions return the existing order instead of creating a duplicate
    CONSTRAINT UQ_Orders_User_IdempotencyKey UNIQUE (UserId, IdempotencyKey),
    CONSTRAINT FK_Orders_Users FOREIGN KEY (UserId) REFERENCES dbo.Users (Id),
    CONSTRAINT FK_Orders_Coupons FOREIGN KEY (CouponId) REFERENCES dbo.Coupons (Id),
    CONSTRAINT FK_Orders_ShippingMethods FOREIGN KEY (ShippingMethodId) REFERENCES dbo.ShippingMethods (Id),
    CONSTRAINT CK_Orders_Status CHECK (Status IN ('PENDING', 'CONFIRMED', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'CANCELLED')),
    CONSTRAINT CK_Orders_PaymentStatus CHECK (PaymentStatus IN
        ('PENDING', 'AUTHORIZED', 'PAID', 'FAILED', 'PARTIALLY_REFUNDED', 'REFUNDED', 'CANCELLED')),
    CONSTRAINT CK_Orders_Amounts CHECK (Subtotal >= 0 AND DiscountTotal >= 0 AND ShippingTotal >= 0
        AND TaxTotal >= 0 AND GrandTotal >= 0 AND RefundedTotal >= 0),
    CONSTRAINT CK_Orders_GrandTotal CHECK (GrandTotal = Subtotal - DiscountTotal + ShippingTotal + TaxTotal),
    CONSTRAINT CK_Orders_Refunded CHECK (RefundedTotal <= GrandTotal)
);
CREATE INDEX IX_Orders_User_PlacedAt ON dbo.Orders (UserId, PlacedAt DESC);
CREATE INDEX IX_Orders_PlacedAt ON dbo.Orders (PlacedAt DESC) INCLUDE (Status, PaymentStatus, GrandTotal, RefundedTotal);
CREATE INDEX IX_Orders_Status_PlacedAt ON dbo.Orders (Status, PlacedAt DESC);
-- Revenue reports: paid orders by payment date
CREATE INDEX IX_Orders_PaidAt ON dbo.Orders (PaidAt) INCLUDE (GrandTotal, RefundedTotal, Currency) WHERE PaidAt IS NOT NULL;

-- Address snapshots: orders keep the address as it was at checkout time
CREATE TABLE dbo.OrderAddresses (
    Id            BIGINT IDENTITY(1,1) NOT NULL,
    OrderId       BIGINT        NOT NULL,
    AddressType   VARCHAR(16)   NOT NULL,
    RecipientName NVARCHAR(200) NOT NULL,
    PhoneNumber   VARCHAR(32)   NULL,
    Line1         NVARCHAR(200) NOT NULL,
    Line2         NVARCHAR(200) NULL,
    City          NVARCHAR(100) NOT NULL,
    Region        NVARCHAR(100) NULL,
    PostalCode    NVARCHAR(20)  NULL,
    CountryCode   CHAR(2)       NOT NULL,
    CONSTRAINT PK_OrderAddresses PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT UQ_OrderAddresses_Order_Type UNIQUE (OrderId, AddressType),
    CONSTRAINT FK_OrderAddresses_Orders FOREIGN KEY (OrderId) REFERENCES dbo.Orders (Id) ON DELETE CASCADE,
    CONSTRAINT CK_OrderAddresses_Type CHECK (AddressType IN ('SHIPPING', 'BILLING'))
);

CREATE TABLE dbo.OrderItems (
    Id                 BIGINT IDENTITY(1,1) NOT NULL,
    OrderId            BIGINT         NOT NULL,
    ProductId          BIGINT         NOT NULL,
    VariantId          BIGINT         NOT NULL,
    ProductName        NVARCHAR(200)  NOT NULL,          -- snapshot
    VariantDescription NVARCHAR(120)  NULL,              -- snapshot, e.g. "Size M / Blue"
    Sku                VARCHAR(64)    NOT NULL,          -- snapshot
    UnitPrice          DECIMAL(19,4)  NOT NULL,          -- price charged per unit (after product discount)
    Quantity           INT            NOT NULL,
    DiscountAmount     DECIMAL(19,4)  NOT NULL CONSTRAINT DF_OrderItems_Discount DEFAULT 0,  -- coupon allocation
    LineTotal          DECIMAL(19,4)  NOT NULL,
    CreatedAt          DATETIME2(3)   NOT NULL CONSTRAINT DF_OrderItems_CreatedAt DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_OrderItems PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT FK_OrderItems_Orders FOREIGN KEY (OrderId) REFERENCES dbo.Orders (Id) ON DELETE CASCADE,
    CONSTRAINT FK_OrderItems_Products FOREIGN KEY (ProductId) REFERENCES dbo.Products (Id),
    CONSTRAINT FK_OrderItems_Variants FOREIGN KEY (VariantId) REFERENCES dbo.ProductVariants (Id),
    CONSTRAINT CK_OrderItems_Quantity CHECK (Quantity > 0),
    CONSTRAINT CK_OrderItems_Amounts CHECK (UnitPrice >= 0 AND DiscountAmount >= 0 AND LineTotal >= 0),
    CONSTRAINT CK_OrderItems_LineTotal CHECK (LineTotal = UnitPrice * Quantity)
);
CREATE INDEX IX_OrderItems_OrderId ON dbo.OrderItems (OrderId);
CREATE INDEX IX_OrderItems_ProductId ON dbo.OrderItems (ProductId) INCLUDE (Quantity, LineTotal);
CREATE INDEX IX_OrderItems_VariantId ON dbo.OrderItems (VariantId);

CREATE TABLE dbo.OrderStatusHistory (
    Id              BIGINT IDENTITY(1,1) NOT NULL,
    OrderId         BIGINT        NOT NULL,
    StatusType      VARCHAR(16)   NOT NULL,              -- FULFILLMENT or PAYMENT
    FromStatus      VARCHAR(20)   NULL,
    ToStatus        VARCHAR(20)   NOT NULL,
    ChangedByUserId BIGINT        NULL,                  -- NULL = system / payment webhook
    Note            NVARCHAR(500) NULL,
    ChangedAt       DATETIME2(3)  NOT NULL CONSTRAINT DF_OrderStatusHistory_ChangedAt DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_OrderStatusHistory PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT FK_OrderStatusHistory_Orders FOREIGN KEY (OrderId) REFERENCES dbo.Orders (Id) ON DELETE CASCADE,
    CONSTRAINT FK_OrderStatusHistory_Users FOREIGN KEY (ChangedByUserId) REFERENCES dbo.Users (Id),
    CONSTRAINT CK_OrderStatusHistory_Type CHECK (StatusType IN ('FULFILLMENT', 'PAYMENT'))
);
CREATE INDEX IX_OrderStatusHistory_Order ON dbo.OrderStatusHistory (OrderId, ChangedAt);

CREATE TABLE dbo.CouponRedemptions (
    Id             BIGINT IDENTITY(1,1) NOT NULL,
    CouponId       BIGINT        NOT NULL,
    UserId         BIGINT        NOT NULL,
    OrderId        BIGINT        NOT NULL,
    DiscountAmount DECIMAL(19,4) NOT NULL,
    RedeemedAt     DATETIME2(3)  NOT NULL CONSTRAINT DF_CouponRedemptions_RedeemedAt DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_CouponRedemptions PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT UQ_CouponRedemptions_Order UNIQUE (OrderId),
    CONSTRAINT FK_CouponRedemptions_Coupons FOREIGN KEY (CouponId) REFERENCES dbo.Coupons (Id),
    CONSTRAINT FK_CouponRedemptions_Users FOREIGN KEY (UserId) REFERENCES dbo.Users (Id),
    CONSTRAINT FK_CouponRedemptions_Orders FOREIGN KEY (OrderId) REFERENCES dbo.Orders (Id),
    CONSTRAINT CK_CouponRedemptions_Amount CHECK (DiscountAmount >= 0)
);
CREATE INDEX IX_CouponRedemptions_Coupon_User ON dbo.CouponRedemptions (CouponId, UserId);

CREATE TABLE dbo.Payments (
    Id                BIGINT IDENTITY(1,1) NOT NULL,
    OrderId           BIGINT         NOT NULL,
    Provider          VARCHAR(32)    NOT NULL,           -- STRIPE, MOCK, ...
    ProviderPaymentId VARCHAR(255)   NULL,               -- e.g. Stripe PaymentIntent id
    ProviderSessionId VARCHAR(255)   NULL,               -- e.g. Stripe Checkout Session id
    Status            VARCHAR(20)    NOT NULL CONSTRAINT DF_Payments_Status DEFAULT 'PENDING',
    Amount            DECIMAL(19,4)  NOT NULL,
    Currency          CHAR(3)        NOT NULL,
    CardBrand         VARCHAR(20)    NULL,               -- non-sensitive display data only
    CardLast4         CHAR(4)        NULL,
    FailureCode       VARCHAR(64)    NULL,
    FailureMessage    NVARCHAR(255)  NULL,
    IdempotencyKey    VARCHAR(64)    NOT NULL,           -- sent to provider on create
    CreatedAt         DATETIME2(3)   NOT NULL CONSTRAINT DF_Payments_CreatedAt DEFAULT SYSUTCDATETIME(),
    UpdatedAt         DATETIME2(3)   NOT NULL CONSTRAINT DF_Payments_UpdatedAt DEFAULT SYSUTCDATETIME(),
    CompletedAt       DATETIME2(3)   NULL,
    Version           BIGINT         NOT NULL CONSTRAINT DF_Payments_Version DEFAULT 0,
    CONSTRAINT PK_Payments PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT UQ_Payments_IdempotencyKey UNIQUE (IdempotencyKey),
    CONSTRAINT FK_Payments_Orders FOREIGN KEY (OrderId) REFERENCES dbo.Orders (Id),
    CONSTRAINT CK_Payments_Status CHECK (Status IN ('PENDING', 'REQUIRES_ACTION', 'AUTHORIZED', 'SUCCEEDED', 'FAILED', 'CANCELLED')),
    CONSTRAINT CK_Payments_Amount CHECK (Amount > 0),
    CONSTRAINT CK_Payments_Last4 CHECK (CardLast4 IS NULL OR CardLast4 NOT LIKE '%[^0-9]%')
);
CREATE INDEX IX_Payments_OrderId ON dbo.Payments (OrderId);
CREATE UNIQUE INDEX UX_Payments_ProviderPaymentId ON dbo.Payments (Provider, ProviderPaymentId) WHERE ProviderPaymentId IS NOT NULL;
CREATE UNIQUE INDEX UX_Payments_ProviderSessionId ON dbo.Payments (Provider, ProviderSessionId) WHERE ProviderSessionId IS NOT NULL;
-- At most one successful payment per order (prevents double charging being recorded as two purchases)
CREATE UNIQUE INDEX UX_Payments_OneSucceededPerOrder ON dbo.Payments (OrderId) WHERE Status = 'SUCCEEDED';

CREATE TABLE dbo.Refunds (
    Id                BIGINT IDENTITY(1,1) NOT NULL,
    PaymentId         BIGINT         NOT NULL,
    OrderId           BIGINT         NOT NULL,
    ProviderRefundId  VARCHAR(255)   NULL,
    Amount            DECIMAL(19,4)  NOT NULL,
    Reason            NVARCHAR(255)  NULL,
    Status            VARCHAR(16)    NOT NULL CONSTRAINT DF_Refunds_Status DEFAULT 'PENDING',
    RequestedByUserId BIGINT         NULL,
    IdempotencyKey    VARCHAR(64)    NOT NULL,
    CreatedAt         DATETIME2(3)   NOT NULL CONSTRAINT DF_Refunds_CreatedAt DEFAULT SYSUTCDATETIME(),
    UpdatedAt         DATETIME2(3)   NOT NULL CONSTRAINT DF_Refunds_UpdatedAt DEFAULT SYSUTCDATETIME(),
    CompletedAt       DATETIME2(3)   NULL,
    CONSTRAINT PK_Refunds PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT UQ_Refunds_IdempotencyKey UNIQUE (IdempotencyKey),
    CONSTRAINT FK_Refunds_Payments FOREIGN KEY (PaymentId) REFERENCES dbo.Payments (Id),
    CONSTRAINT FK_Refunds_Orders FOREIGN KEY (OrderId) REFERENCES dbo.Orders (Id),
    CONSTRAINT FK_Refunds_Users FOREIGN KEY (RequestedByUserId) REFERENCES dbo.Users (Id),
    CONSTRAINT CK_Refunds_Status CHECK (Status IN ('PENDING', 'SUCCEEDED', 'FAILED')),
    CONSTRAINT CK_Refunds_Amount CHECK (Amount > 0)
);
CREATE INDEX IX_Refunds_OrderId ON dbo.Refunds (OrderId);
CREATE INDEX IX_Refunds_CompletedAt ON dbo.Refunds (CompletedAt) INCLUDE (Amount) WHERE Status = 'SUCCEEDED';
CREATE UNIQUE INDEX UX_Refunds_ProviderRefundId ON dbo.Refunds (ProviderRefundId) WHERE ProviderRefundId IS NOT NULL;

-- Webhook de-duplication: providers retry deliveries, each event is processed once
CREATE TABLE dbo.PaymentWebhookEvents (
    Id              BIGINT IDENTITY(1,1) NOT NULL,
    Provider        VARCHAR(32)   NOT NULL,
    ProviderEventId VARCHAR(255)  NOT NULL,
    EventType       VARCHAR(100)  NOT NULL,
    Status          VARCHAR(16)   NOT NULL CONSTRAINT DF_PaymentWebhookEvents_Status DEFAULT 'RECEIVED',
    ErrorMessage    NVARCHAR(500) NULL,
    ReceivedAt      DATETIME2(3)  NOT NULL CONSTRAINT DF_PaymentWebhookEvents_ReceivedAt DEFAULT SYSUTCDATETIME(),
    ProcessedAt     DATETIME2(3)  NULL,
    CONSTRAINT PK_PaymentWebhookEvents PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT UQ_PaymentWebhookEvents_ProviderEvent UNIQUE (Provider, ProviderEventId),
    CONSTRAINT CK_PaymentWebhookEvents_Status CHECK (Status IN ('RECEIVED', 'PROCESSED', 'IGNORED', 'FAILED'))
);
CREATE INDEX IX_PaymentWebhookEvents_ReceivedAt ON dbo.PaymentWebhookEvents (ReceivedAt);

-- Append-only stock ledger. ProductVariants.StockQuantity is the current balance,
-- updated in the same transaction as the ledger row.
CREATE TABLE dbo.InventoryTransactions (
    Id              BIGINT IDENTITY(1,1) NOT NULL,
    VariantId       BIGINT        NOT NULL,
    ChangeQuantity  INT           NOT NULL,              -- +restock / -sale
    QuantityAfter   INT           NOT NULL,
    Reason          VARCHAR(24)   NOT NULL,
    OrderId         BIGINT        NULL,
    Note            NVARCHAR(255) NULL,
    CreatedByUserId BIGINT        NULL,
    CreatedAt       DATETIME2(3)  NOT NULL CONSTRAINT DF_InventoryTransactions_CreatedAt DEFAULT SYSUTCDATETIME(),
    CONSTRAINT PK_InventoryTransactions PRIMARY KEY CLUSTERED (Id),
    CONSTRAINT FK_InventoryTransactions_Variants FOREIGN KEY (VariantId) REFERENCES dbo.ProductVariants (Id),
    CONSTRAINT FK_InventoryTransactions_Orders FOREIGN KEY (OrderId) REFERENCES dbo.Orders (Id),
    CONSTRAINT FK_InventoryTransactions_Users FOREIGN KEY (CreatedByUserId) REFERENCES dbo.Users (Id),
    CONSTRAINT CK_InventoryTransactions_Change CHECK (ChangeQuantity <> 0),
    CONSTRAINT CK_InventoryTransactions_After CHECK (QuantityAfter >= 0),
    CONSTRAINT CK_InventoryTransactions_Reason CHECK (Reason IN
        ('INITIAL', 'RESTOCK', 'SALE', 'ORDER_CANCELLED', 'RETURN', 'ADJUSTMENT', 'DAMAGED'))
);
CREATE INDEX IX_InventoryTransactions_Variant_CreatedAt ON dbo.InventoryTransactions (VariantId, CreatedAt DESC);
CREATE INDEX IX_InventoryTransactions_OrderId ON dbo.InventoryTransactions (OrderId) WHERE OrderId IS NOT NULL;
